use crate::model::{Job, Summary};

pub fn run(jobs: &[Job], budget: i64) -> Summary {
    let mut completed = vec![false; jobs.len()];
    let mut order = Vec::with_capacity(jobs.len());
    let mut remaining = budget;

    loop {
        let next = jobs.iter().filter(|job| {
            !completed[job.id as usize]
                && job.cost <= remaining
                && job.deps.iter().all(|&id| completed[id as usize])
        }).min_by_key(|job| job.id);

        let Some(job) = next else {
            break;
        };
        completed[job.id as usize] = true;
        remaining -= job.cost;
        order.push(job.id);
    }

    Summary {
        spent: budget - remaining,
        blocked: (jobs.len() - order.len()) as i64,
        order,
    }
}

